const OWNER_ID = '00000000-0000-4000-8000-000000000001';
const OTHER_ID = '00000000-0000-4000-8000-000000000002';
const ACTIONS: AccessAction[] = ['view', 'comment', 'edit', 'share', 'delete'];

const logger = { debug: vi.fn() } as unknown as PinoLogger;
const policy = new AccessPolicyService(logger);

function actor(userId: string, via: Actor['via'] = 'web'): Actor {
  return { userId, via };
}

function artifact(overrides: Partial<AccessTarget> = {}): AccessTarget {
  return {
    id: '00000000-0000-4000-8000-0000000000aa',
    ownerId: OWNER_ID,
    visibility: 'private',
    deletedAt: null,
    ...overrides,
  };
}

describe('AccessPolicyService (owner-only)', () => {
  it.each(ACTIONS)('lets the owner %s, from the web and from MCP', (action) => {
    expect(policy.can(actor(OWNER_ID), action, artifact())).toBe(true);
    expect(policy.can(actor(OWNER_ID, 'mcp'), action, artifact())).toBe(true);
    expect(() => policy.assertCan(actor(OWNER_ID), action, artifact())).not.toThrow();
  });

  it.each(ACTIONS)('denies %s to anyone else with NOT_FOUND', (action) => {
    expect(policy.can(actor(OTHER_ID), action, artifact())).toBe(false);
    expect(() => policy.assertCan(actor(OTHER_ID), action, artifact())).toThrow(
      expect.objectContaining({ code: ErrorCode.NOT_FOUND }),
    );
  });

  it('does not open public artifacts to others yet (step 12)', () => {
    expect(policy.can(actor(OTHER_ID), 'view', artifact({ visibility: 'public' }))).toBe(false);
  });

  it.each(ACTIONS)('denies %s on a deleted artifact, even to its owner', (action) => {
    const deleted = artifact({ deletedAt: new Date() });
    expect(policy.can(actor(OWNER_ID), action, deleted)).toBe(false);
    expect(() => policy.assertCan(actor(OWNER_ID), action, deleted)).toThrow(
      expect.objectContaining({ code: ErrorCode.NOT_FOUND }),
    );
  });

  it('gives the same message for denied and missing artifacts', () => {
    expect(() => policy.assertCan(actor(OTHER_ID), 'view', artifact())).toThrow(
      'Artifact not found.',
    );
  });

  it('restricts list queries to non-deleted artifacts the actor owns', () => {
    const qb = { andWhere: vi.fn().mockReturnThis() };
    policy.restrictToViewable(
      qb as unknown as SelectQueryBuilder<AccessTarget>,
      'artifact',
      actor(OWNER_ID),
    );
    expect(qb.andWhere.mock.calls).toEqual([
      ['artifact.deletedAt IS NULL'],
      ['artifact.ownerId = :accessViewerId', { accessViewerId: OWNER_ID }],
    ]);
  });

  it('logs denials at debug with ids and the reason only', () => {
    vi.mocked(logger.debug).mockClear();
    try {
      policy.assertCan(actor(OTHER_ID), 'edit', artifact());
    } catch {
      // Expected.
    }
    expect(logger.debug).toHaveBeenCalledWith(
      {
        userId: OTHER_ID,
        artifactId: '00000000-0000-4000-8000-0000000000aa',
        action: 'edit',
        reason: 'not_owner',
      },
      'Access denied',
    );
  });
});
import { Injectable } from '@nestjs/common';
import { ErrorCode } from '@artifact-hub/shared';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import type { ObjectLiteral, SelectQueryBuilder } from 'typeorm';
import type { Actor } from '../auth/auth.types.js';
import { AppError } from '../common/errors/app-error.js';
import type { AccessAction, AccessTarget, DenialReason } from './access.types.js';

export const ARTIFACT_NOT_FOUND_MESSAGE = 'Artifact not found.';

/**
 * The only place that decides who may do what with an artifact (plan §4). REST and MCP both go
 * through it. Owner-only for now; public visibility and shares extend it in steps 12–14.
 */
@Injectable()
export class AccessPolicyService {
  constructor(@InjectPinoLogger(AccessPolicyService.name) private readonly logger: PinoLogger) {}

  can(actor: Actor, action: AccessAction, artifact: AccessTarget): boolean {
    return this.denialReason(actor, action, artifact) === null;
  }

  /**
   * Throws unless `actor` may perform `action`. Callers who may not even view the artifact get
   * `NOT_FOUND`, exactly as if it did not exist; those who may view it but not do more get
   * `FORBIDDEN`.
   */
  assertCan(actor: Actor, action: AccessAction, artifact: AccessTarget): void {
    const reason = this.denialReason(actor, action, artifact);
    if (reason === null) return;

    this.logger.debug(
      { userId: actor.userId, artifactId: artifact.id, action, reason },
      'Access denied',
    );
    if (action !== 'view' && this.can(actor, 'view', artifact)) {
      throw new AppError(ErrorCode.FORBIDDEN, "You don't have permission to do that.");
    }
    throw new AppError(ErrorCode.NOT_FOUND, ARTIFACT_NOT_FOUND_MESSAGE);
  }

  /**
   * Narrows a query on artifacts (selected as `alias`) to those `actor` may view: the SQL form
   * of `can(actor, 'view', …)`, for lists. Keep the two in step.
   */
  restrictToViewable<T extends ObjectLiteral>(
    qb: SelectQueryBuilder<T>,
    alias: string,
    actor: Actor,
  ): SelectQueryBuilder<T> {
    return qb
      .andWhere(`${alias}.deletedAt IS NULL`)
      .andWhere(`${alias}.ownerId = :accessViewerId`, { accessViewerId: actor.userId });
  }

  private denialReason(
    actor: Actor,
    _action: AccessAction,
    artifact: AccessTarget,
  ): DenialReason | null {
    if (artifact.deletedAt) return 'deleted';
    if (artifact.ownerId !== actor.userId) return 'not_owner';
    return null;
  }
}
