import type { Readable } from 'node:stream';

export interface MultipartUploadOptions {
  /** Largest file accepted; the file stream itself is limited by `ContentInspectorService`. */
  maxFileBytes: number;
}

export interface MultipartUpload {
  /** Text fields sent before the file. Fields after it are ignored. */
  fields: Record<string, string>;
  file: {
    /** Unread: consume it, or call `discard()`. */
    stream: Readable;
    /** As sent by the client; sanitize before storing or displaying. */
    filename: string;
  };
  /**
   * Stops parsing and drains the rest of the request, so an error response still reaches
   * the client. Call it when the upload is rejected before `file.stream` has been consumed.
   */
  discard(): void;
}
import type { IncomingMessage } from 'node:http';
import { PassThrough } from 'node:stream';
import { text } from 'node:stream/consumers';
import { ErrorCode } from '@artifact-hub/shared';
import { readMultipartUpload } from './read-multipart-upload.js';

const BOUNDARY = 'test-boundary';
const MAX = 1024;

type FakeRequest = PassThrough & { headers: IncomingMessage['headers']; complete: boolean };

/** A request stream with headers; `complete` turns true when the body has been fully sent. */
function fakeRequest(headers: IncomingMessage['headers'] = {}): FakeRequest {
  const req = new PassThrough() as FakeRequest;
  req.headers = { 'content-type': `multipart/form-data; boundary=${BOUNDARY}`, ...headers };
  req.complete = false;
  return req;
}

function field(name: string, value: string): string {
  return `--${BOUNDARY}\r\nContent-Disposition: form-data; name="${name}"\r\n\r\n${value}\r\n`;
}

function fileHeader(name: string, filename: string): string {
  return (
    `--${BOUNDARY}\r\nContent-Disposition: form-data; name="${name}"; filename="${filename}"\r\n` +
    'Content-Type: application/octet-stream\r\n\r\n'
  );
}

const END = `\r\n--${BOUNDARY}--\r\n`;

function send(req: FakeRequest, body: string): void {
  req.complete = true;
  req.end(body);
}

const read = (req: FakeRequest) =>
  readMultipartUpload(req as unknown as IncomingMessage, { maxFileBytes: MAX });

describe('readMultipartUpload', () => {
  it('resolves with the fields sent before the file and the file as a stream', async () => {
    const req = fakeRequest();
    const upload = read(req);
    send(
      req,
      field('metadata', '{"title":"x"}') + fileHeader('file', 'page.html') + '<p>hi</p>' + END,
    );

    const { fields, file } = await upload;
    expect(fields).toEqual({ metadata: '{"title":"x"}' });
    expect(file.filename).toBe('page.html');
    expect(await text(file.stream)).toBe('<p>hi</p>');
  });

  it('ignores fields sent after the file', async () => {
    const req = fakeRequest();
    const upload = read(req);
    send(req, fileHeader('file', 'b.md') + '# yes\r\n' + field('metadata', 'late') + END.slice(2));

    const { fields, file } = await upload;
    expect(fields).toEqual({});
    expect(await text(file.stream)).toBe('# yes');
  });

  it('accepts exactly one file part, named "file"', async () => {
    const req = fakeRequest();
    const upload = read(req);
    send(req, fileHeader('attachment', 'a.md') + '# no\r\n' + fileHeader('file', 'b.md') + END);
    await expect(upload).rejects.toMatchObject({ code: ErrorCode.BAD_REQUEST });
  });

  it('rejects an upload without a file', async () => {
    const req = fakeRequest();
    const upload = read(req);
    send(req, field('metadata', '{}') + END.slice(2));
    await expect(upload).rejects.toMatchObject({
      code: ErrorCode.BAD_REQUEST,
      message: expect.stringContaining('"file"'),
    });
  });

  it('rejects requests that are not multipart', async () => {
    const req = fakeRequest({ 'content-type': 'application/json' });
    await expect(read(req)).rejects.toMatchObject({ code: ErrorCode.BAD_REQUEST });
  });

  it('rejects a Content-Length over the limit before reading the body', async () => {
    const req = fakeRequest({ 'content-length': String(10 * 1024 * 1024) });
    await expect(read(req)).rejects.toMatchObject({
      code: ErrorCode.ARTIFACT_TOO_LARGE,
      details: { maxBytes: MAX },
    });
  });

  it('rejects oversized text fields', async () => {
    const req = fakeRequest();
    const upload = read(req);
    send(req, field('metadata', 'x'.repeat(20 * 1024)) + fileHeader('file', 'a.md') + '#' + END);
    await expect(upload).rejects.toMatchObject({
      code: ErrorCode.BAD_REQUEST,
      message: expect.stringContaining('too long'),
    });
  });

  it('fails the file stream when the client disconnects mid-upload', async () => {
    const req = fakeRequest();
    const upload = read(req);
    req.write(fileHeader('file', 'big.md') + '# partial');

    const { file } = await upload;
    const content = text(file.stream);
    req.destroy();
    await expect(content).rejects.toThrow();
  });
});
import type { IncomingMessage } from 'node:http';
import { ErrorCode } from '@artifact-hub/shared';
import busboy from 'busboy';
import { AppError } from '../../common/errors/app-error.js';
import { ByteMeter } from '../content/byte-meter.js';
import type { MultipartUpload, MultipartUploadOptions } from './multipart.types.js';

/** The form field that carries the file. */
export const FILE_FIELD = 'file';
const MAX_FIELDS = 5;
const MAX_FIELD_BYTES = 16 * 1024;
/** Room for the text fields and part headers on top of the file itself. */
const MULTIPART_OVERHEAD_BYTES = MAX_FIELDS * MAX_FIELD_BYTES + 16 * 1024;

/**
 * Streams a `multipart/form-data` upload: resolves as soon as the `file` part starts, with the
 * text fields sent before it and the file as an unread stream. Nothing is buffered in memory
 * or on disk. Clients must send their fields first (`FormData` keeps insertion order).
 */
export function readMultipartUpload(
  req: IncomingMessage,
  { maxFileBytes }: MultipartUploadOptions,
): Promise<MultipartUpload> {
  const maxRequestBytes = maxFileBytes + MULTIPART_OVERHEAD_BYTES;

  // Browsers always send Content-Length for FormData: reject before reading anything.
  if (Number(req.headers['content-length']) > maxRequestBytes) {
    discard(req);
    return Promise.reject(ByteMeter.tooLarge(maxFileBytes));
  }

  let parser: busboy.Busboy;
  try {
    parser = busboy({
      headers: req.headers,
      limits: { files: 1, fields: MAX_FIELDS, fieldSize: MAX_FIELD_BYTES, parts: MAX_FIELDS + 1 },
    });
  } catch {
    discard(req);
    return Promise.reject(badRequest('Send the file as multipart/form-data.'));
  }

  return new Promise((resolve, reject) => {
    const fields: Record<string, string> = {};
    let settled = false;

    const stop = () => {
      req.unpipe(parser);
      discard(req);
    };
    const fail = (error: AppError) => {
      if (settled) return;
      settled = true;
      stop();
      reject(error);
    };

    parser.on('field', (name, value, info) => {
      if (settled) return;
      if (info.valueTruncated) {
        fail(badRequest(`The "${name.slice(0, 40)}" field is too long.`));
        return;
      }
      fields[name] = value;
    });
    parser.on('file', (name, stream, info) => {
      if (settled || name !== FILE_FIELD) {
        stream.resume();
        return;
      }
      settled = true;
      resolve({ fields, file: { stream, filename: info.filename ?? '' }, discard: stop });
    });
    parser.on('error', () => fail(badRequest('The upload could not be read.')));
    parser.on('close', () => fail(badRequest(`Add a file in the "${FILE_FIELD}" field.`)));

    // Busboy is not told when the client goes away; without this the file stream never ends.
    req.on('error', (error) => parser.destroy(error));
    req.on('close', () => {
      if (!req.complete) parser.destroy(new Error('Request aborted'));
    });
    req.pipe(parser);
  });
}

/**
 * Reads and drops the rest of the request, so the error response reaches the client instead
 * of a connection reset. Node's `requestTimeout` (5 min) bounds how long a client can keep
 * sending.
 */
function discard(req: IncomingMessage): void {
  if (req.complete || req.destroyed) return;
  req.resume();
}

function badRequest(message: string): AppError {
  return new AppError(ErrorCode.BAD_REQUEST, message);
}
import { createParamDecorator, type ExecutionContext, SetMetadata } from '@nestjs/common';
import type { Request } from 'express';
import type { Actor } from './auth.types.js';

export const IS_PUBLIC_KEY = 'auth:isPublic';

/** Opts a route (or controller) out of authentication. Everything else requires a session. */
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);

/** The authenticated `Actor`. Only valid on routes that are not `@Public()`. */
export const CurrentActor = createParamDecorator((_data: unknown, ctx: ExecutionContext): Actor => {
