import { type Artifact, formatBytes } from '@artifact-hub/shared';
import { zodResolver } from '@hookform/resolvers/zod';
import { type ReactNode, useState } from 'react';
import { useForm } from 'react-hook-form';
import { useNavigate } from 'react-router';
import { toast } from 'sonner';
import { FormError, TextAreaField, TextField } from '@/components/form-fields.tsx';
import { Button } from '@/components/ui/button.tsx';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog.tsx';
import { useAppConfig } from '@/features/config/use-app-config.ts';
import { isApiError } from '@/lib/api/api-error.ts';
import { applyServerError } from '@/lib/forms/apply-server-error.ts';
import { titleFromFilename } from './artifact-types.ts';
import type { PublishFormOutput, PublishFormValues } from './artifacts.types.ts';
import { FileDropZone } from './file-drop-zone.tsx';
import { publishFormSchema } from './publish-form-schema.ts';
import { usePublishArtifact } from './use-artifacts.ts';

/** Opens the publish dialog from `children` (the trigger button). */
export function PublishDialog({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const publish = usePublishArtifact();
  const navigate = useNavigate();

  const onOpenChange = (next: boolean) => {
    // Keep the dialog open while the upload is in flight.
    if (publish.isPending) return;
    if (next) publish.reset();
    setOpen(next);
  };

  const onPublished = (artifact: Artifact) => {
    setOpen(false);
    toast.success(`Published “${artifact.title}”`);
    void navigate(`/artifacts/${artifact.id}`);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Publish an artifact</DialogTitle>
          <DialogDescription>
            Only you can see it until you share it or make it public.
          </DialogDescription>
        </DialogHeader>
        <PublishForm
          onSubmit={(file, metadata) => publish.mutateAsync({ file, metadata })}
          onPublished={onPublished}
        />
      </DialogContent>
    </Dialog>
  );
}

function PublishForm({
  onSubmit,
  onPublished,
}: {
  onSubmit: (file: File, metadata: PublishFormOutput) => Promise<Artifact>;
  onPublished: (artifact: Artifact) => void;
}) {
  const { data: config } = useAppConfig();
  const [file, setFile] = useState<File | null>(null);
  const [fileError, setFileError] = useState<string>();
  const {
    register,
    handleSubmit,
    setError,
    setValue,
    getFieldState,
    formState: { errors, isSubmitting },
  } = useForm<PublishFormValues, unknown, PublishFormOutput>({
    resolver: zodResolver(publishFormSchema),
    defaultValues: { title: '', description: '', tags: '' },
  });

  const chooseFile = (chosen: File) => {
    const maxBytes = config?.maxArtifactBytes;
    if (chosen.size === 0) {
      setFileError('This file is empty.');
      return;
    }
    if (maxBytes && chosen.size > maxBytes) {
      setFileError(
        `This file is ${formatBytes(chosen.size)}. The limit is ${formatBytes(maxBytes)}.`,
      );
      return;
    }
    setFile(chosen);
    setFileError(undefined);
    // Default the title to the file name, unless the user already typed one.
    if (!getFieldState('title').isDirty) {
      setValue('title', titleFromFilename(chosen.name), { shouldValidate: !!errors.title });
    }
  };

  const submit = handleSubmit(async (metadata) => {
    if (!file) return;
    try {
      onPublished(await onSubmit(file, metadata));
    } catch (error) {
      if (isApiError(error, 'UNSUPPORTED_TYPE') || isApiError(error, 'ARTIFACT_TOO_LARGE')) {
        setFileError(error.message);
        return;
      }
      applyServerError(error, setError, ['title', 'description', 'tags']);
    }
  });

  return (
    <form
      noValidate
      className="grid gap-4"
      onSubmit={(event) => {
        // Report a missing file together with any field errors.
        if (!file) setFileError('Choose a file to publish.');
        void submit(event);
      }}
    >
      <FormError message={errors.root?.server?.message} />
      <FileDropZone
        file={file}
        onFileChange={chooseFile}
        maxBytes={config?.maxArtifactBytes}
        error={fileError}
        disabled={isSubmitting}
      />
      <TextField label="Title" error={errors.title?.message} {...register('title')} />
      <TextAreaField
        label="Description"
        rows={3}
        error={errors.description?.message}
        {...register('description')}
      />
      <TextField
        label="Tags"
        hint="Separate tags with commas, e.g. marketing, q3"
        error={errors.tags?.message}
        {...register('tags')}
      />
      <DialogFooter>
        <DialogClose asChild>
          <Button type="button" variant="outline" disabled={isSubmitting}>
            Cancel
          </Button>
        </DialogClose>
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? 'Publishing…' : 'Publish'}
        </Button>
      </DialogFooter>
    </form>
  );
}
import { artifactTagsSchema, createArtifactRequestSchema } from '@artifact-hub/shared';
import { z } from 'zod';

/**
 * The publish form, validated with the same rules as the API. Tags are typed as one
 * comma-separated string; any tag problem is reported on that field.
 */
export const publishFormSchema = z.object({
  title: createArtifactRequestSchema.shape.title,
  description: createArtifactRequestSchema.shape.description,
  tags: z.string().transform((value, ctx) => {
    const tags = value
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
    const result = artifactTagsSchema.safeParse(tags);
    if (result.success) return result.data;
    ctx.addIssue({ code: 'custom', message: result.error.issues[0]?.message ?? 'Invalid tags.' });
    return z.NEVER;
  }),
});
import type { z } from 'zod';
import type { publishFormSchema } from './publish-form-schema.ts';

export interface ArtifactListParams {
  scope: 'mine';
  /** 1-based. */
  page: number;
  pageSize: number;
}

/** What the publish form holds before the schema normalizes it (tags as one string). */
export type PublishFormValues = z.input<typeof publishFormSchema>;
/** What it submits. */
export type PublishFormOutput = z.output<typeof publishFormSchema>;
import { apiErrorBodySchema, ErrorCode } from '@artifact-hub/shared';
import { ApiError } from './api-error.ts';
import type { ApiRequestOptions } from './api.types.ts';

const NETWORK_ERROR_MESSAGE = "Can't reach the server. Check your connection and try again.";
const UNEXPECTED_RESPONSE_MESSAGE = 'The server sent an unexpected response. Please try again.';

/**
 * Calls the API on the same origin with the session cookie. Throws `ApiError` for error
 * responses and network failures, and validates success bodies with `schema`. A `FormData`
 * body is sent as multipart (the browser sets the boundary); anything else as JSON.
 */
export async function apiRequest<T = void>(
  path: string,
  { method = 'GET', body, schema, signal }: ApiRequestOptions<T> = {},
): Promise<T> {
  const isJson = body !== undefined && !(body instanceof FormData);
  const res = await send(path, {
    method,
    signal,
    headers: {
      Accept: 'application/json',
      ...(isJson ? { 'Content-Type': 'application/json' } : {}),
    },
    body: isJson ? JSON.stringify(body) : (body as FormData | undefined),
  });

  const payload: unknown = res.status === 204 ? undefined : await res.json().catch(() => undefined);
  if (!res.ok) throw toApiError(res.status, payload);

  if (!schema) return undefined as T;
  const parsed = schema.safeParse(payload);
  if (!parsed.success) {
    throw new ApiError(res.status, ErrorCode.INTERNAL_ERROR, UNEXPECTED_RESPONSE_MESSAGE);
  }
  return parsed.data;
}

/**
 * Fetches non-JSON content (artifact bytes) from the API, with the same error handling as
 * `apiRequest`. Returns the successful response for the caller to read.
 */
export async function apiFetchContent(
  path: string,
  { signal }: { signal?: AbortSignal } = {},
): Promise<Response> {
  const res = await send(path, { signal });
  if (!res.ok) throw toApiError(res.status, await res.json().catch(() => undefined));
  return res;
}

async function send(path: string, init: RequestInit): Promise<Response> {
  try {
    return await fetch(`/api${path}`, { ...init, credentials: 'same-origin' });
  } catch (error) {
    if (init.signal?.aborted) throw error;
    throw new ApiError(0, 'NETWORK_ERROR', NETWORK_ERROR_MESSAGE);
  }
}

function toApiError(status: number, payload: unknown): ApiError {
  const parsed = apiErrorBodySchema.safeParse(payload);
  if (!parsed.success) {
    return new ApiError(status, ErrorCode.INTERNAL_ERROR, UNEXPECTED_RESPONSE_MESSAGE);
  }
  const { code, message, details, requestId } = parsed.data.error;
  return new ApiError(status, code, message, details, requestId);
}
import { type Artifact, type ArtifactMimeType, ErrorCode, type User } from '@artifact-hub/shared';
import { vi } from 'vitest';

interface Account {
  user: User;
  password: string;
}

function json(status: number, body?: unknown): Response {
  if (body === undefined) return new Response(null, { status });
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

function error(status: number, code: ErrorCode, message: string): Response {
  return json(status, { error: { code, message, requestId: 'test-req' } });
}

const LIST_ROUTE = /^GET \/api\/artifacts\?(.*)$/;
const ARTIFACT_ROUTE = /^GET \/api\/artifacts\/([^/?]+)$/;
const CONTENT_ROUTE = /^GET \/api\/artifacts\/([^/?]+)\/versions\/(\d+)\/content$/;

const MIME_BY_EXTENSION: Record<string, ArtifactMimeType> = {
  html: 'text/html',
  svg: 'image/svg+xml',
  md: 'text/markdown',
  png: 'image/png',
  pdf: 'application/pdf',
};

/**
 * Stubs `fetch` with an in-memory version of the API (auth, config, publishing and reading
 * artifacts), so component tests run the real API client, hooks and routes.
 */
export function installFakeApi() {
  const accounts = new Map<string, Account>();
  const artifacts = new Map<string, { artifact: Artifact; content: BodyInit }>();
  /** Every publish request's form, in the order its parts were appended. */
  const publishedForms: FormData[] = [];
  let nextPublishResponse: Response | null = null;
  let maxArtifactBytes = 10 * 1024 * 1024;
  let signedIn: User | null = null;

  const publish = (form: FormData): Response => {
    publishedForms.push(form);
    if (nextPublishResponse) {
      const response = nextPublishResponse;
      nextPublishResponse = null;
      return response;
    }
    const metadata = JSON.parse(String(form.get('metadata')));
    const file = form.get('file') as File;
    const now = new Date().toISOString();
    const artifact: Artifact = {
      id: crypto.randomUUID(),
      title: metadata.title,
      description: metadata.description ?? '',
      tags: metadata.tags ?? [],
      visibility: 'private',
      status: 'published',
      metadataSource: 'user',
      owner: { id: signedIn!.id, displayName: signedIn!.displayName },
      currentVersion: {
        id: crypto.randomUUID(),
        versionNo: 1,
        mimeType: MIME_BY_EXTENSION[file.name.split('.').pop() ?? ''] ?? 'text/markdown',
        sizeBytes: file.size,
        sha256: '0'.repeat(64),
        originalFilename: file.name,
        changeNote: null,
        createdAt: now,
      },
      latestVersionNo: 1,
      createdAt: now,
      updatedAt: now,
    };
    artifacts.set(artifact.id, { artifact, content: file });
    return json(201, { artifact });
  };

  const listMine = (query: URLSearchParams): Response => {
    const page = Number(query.get('page') ?? 1);
    const pageSize = Number(query.get('pageSize') ?? 24);
    const mine = [...artifacts.values()]
      .map(({ artifact }) => artifact)
      .filter((artifact) => artifact.owner.id === signedIn?.id)
      .toSorted((a, b) => b.updatedAt.localeCompare(a.updatedAt));
    const items = mine.slice((page - 1) * pageSize, page * pageSize);
    return json(200, { items, page, pageSize, total: mine.length });
  };

  const fetchMock = vi.fn(async (input: string, init: RequestInit = {}) => {
    const body = typeof init.body === 'string' ? JSON.parse(init.body) : undefined;
    const route = `${init.method ?? 'GET'} ${input}`;

    if (route === 'GET /api/config') return json(200, { maxArtifactBytes });
    const listMatch = LIST_ROUTE.exec(route);
    if (listMatch) {
      if (!signedIn) return error(401, ErrorCode.UNAUTHENTICATED, 'Please log in.');
      return listMine(new URLSearchParams(listMatch[1]));
    }
    if (route === 'POST /api/artifacts' && init.body instanceof FormData) {
      if (!signedIn) return error(401, ErrorCode.UNAUTHENTICATED, 'Please log in.');
      return publish(init.body);
    }

    const artifactMatch = ARTIFACT_ROUTE.exec(route) ?? CONTENT_ROUTE.exec(route);
    if (artifactMatch) {
      if (!signedIn) return error(401, ErrorCode.UNAUTHENTICATED, 'Please log in.');
      const stored = artifacts.get(decodeURIComponent(artifactMatch[1] ?? ''));
      if (!stored) return error(404, ErrorCode.NOT_FOUND, 'Artifact not found.');
      if (artifactMatch[2] === undefined) return json(200, { artifact: stored.artifact });
      return new Response(stored.content, { status: 200 });
    }

    switch (route) {
      case 'GET /api/auth/me':
        return signedIn
          ? json(200, { user: signedIn })
          : error(401, ErrorCode.UNAUTHENTICATED, 'Please log in.');
      case 'POST /api/auth/login': {
        const account = accounts.get(body.email);
        if (!account || account.password !== body.password) {
          return error(401, ErrorCode.UNAUTHENTICATED, 'Invalid email or password.');
        }
        signedIn = account.user;
        return json(200, { user: signedIn });
      }
      case 'POST /api/auth/signup': {
        if (accounts.has(body.email)) {
          return error(409, ErrorCode.CONFLICT, 'An account with this email already exists.');
        }
        const user: User = {
          id: crypto.randomUUID(),
          email: body.email,
          displayName: body.displayName,
          createdAt: new Date().toISOString(),
        };
        accounts.set(body.email, { user, password: body.password });
        signedIn = user;
        return json(201, { user });
      }
      case 'POST /api/auth/logout':
        signedIn = null;
        return json(204);
      default:
        return error(404, ErrorCode.NOT_FOUND, `No fake for ${route}`);
    }
  });
  vi.stubGlobal('fetch', fetchMock);

  return {
    fetchMock,
    addAccount(email: string, password: string, displayName = 'Ada Lovelace') {
      const user: User = {
        id: crypto.randomUUID(),
        email,
        displayName,
        createdAt: new Date().toISOString(),
      };
      accounts.set(email, { user, password });
      return user;
    },
    publishedForms,
    /** The next publish request fails with this error instead of succeeding. */
    failNextPublish(status: number, code: ErrorCode, message: string, details?: unknown) {
      nextPublishResponse = json(status, {
        error: { code, message, details, requestId: 'test-req' },
      });
    },
    setMaxArtifactBytes(bytes: number) {
      maxArtifactBytes = bytes;
    },
    /** Serves `artifact` and, for any of its versions, `content`. */
    addArtifact(artifact: Artifact, content: BodyInit = '') {
      artifacts.set(artifact.id, { artifact, content });
    },
    signIn(user: User) {
      signedIn = user;
    },
    /** Simulates the session expiring on the server. */
    expireSession() {
      signedIn = null;
    },
    calls(route: string) {
      return fetchMock.mock.calls.filter(
        ([url, init]) => `${init?.method ?? 'GET'} ${url}` === route,
      ).length;
    },
  };
}
import { QueryClientProvider } from '@tanstack/react-query';
import { render } from '@testing-library/react';
import { createMemoryRouter, RouterProvider } from 'react-router';
import { createQueryClient } from '@/lib/query-client.ts';
