export function ArtifactViewer({
  artifact,
  version,
}: {
  artifact: Pick<Artifact, 'id' | 'title'>;
  version: ArtifactVersion;
}) {
  const src = artifactContentUrl(artifact.id, version.versionNo);

  switch (viewerKind(version.mimeType)) {
