import { type Artifact, VERSION_CHANGE_NOTE_MAX_LENGTH } from '@artifact-hub/shared';
import { type FormEvent, type ReactNode, useState } from 'react';
import { toast } from 'sonner';
import { FormError, TextAreaField } from '@/components/form-fields.tsx';
import { Button } from '@/components/ui/button.tsx';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog.tsx';
import { useAppConfig } from '@/features/config/use-app-config.ts';
import { describeError, isApiError } from '@/lib/api/api-error.ts';
import { fileProblem } from './file-checks.ts';
import { FileDropZone } from './file-drop-zone.tsx';
import { usePublishVersion } from './use-artifacts.ts';

/**
 * Uploads new content for `artifact` as its next version, from `children` (the trigger).
 * `onPublished` runs with the updated artifact once the dialog has closed.
 */
export function NewVersionDialog({
  artifact,
  onPublished,
  children,
}: {
  artifact: Artifact;
  onPublished: (artifact: Artifact) => void;
  children: ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const publish = usePublishVersion(artifact.id);

  const onOpenChange = (next: boolean) => {
    // Keep the dialog open while the upload is in flight.
    if (publish.isPending) return;
    if (next) publish.reset();
    setOpen(next);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Upload a new version</DialogTitle>
          <DialogDescription>
            It becomes v{artifact.latestVersionNo + 1} of “{artifact.title}”. Earlier versions stay
            available.
          </DialogDescription>
        </DialogHeader>
        <NewVersionForm
          onSubmit={(file, changeNote) => publish.mutateAsync({ file, metadata: { changeNote } })}
          onPublished={(updated) => {
            setOpen(false);
            toast.success(`Published v${updated.latestVersionNo}`);
            onPublished(updated);
          }}
        />
      </DialogContent>
    </Dialog>
  );
}

function NewVersionForm({
  onSubmit,
  onPublished,
}: {
  onSubmit: (file: File, changeNote: string) => Promise<Artifact>;
  onPublished: (artifact: Artifact) => void;
}) {
  const { data: config } = useAppConfig();
  const [file, setFile] = useState<File | null>(null);
  const [fileError, setFileError] = useState<string>();
  const [changeNote, setChangeNote] = useState('');
  const [noteError, setNoteError] = useState<string>();
  const [formError, setFormError] = useState<string>();
  const [submitting, setSubmitting] = useState(false);

  const chooseFile = (chosen: File) => {
    const problem = fileProblem(chosen, config?.maxArtifactBytes);
    setFileError(problem);
    if (!problem) setFile(chosen);
  };

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    setFormError(undefined);
    if (!file) {
      setFileError('Choose a file to upload.');
      return;
    }
    if (changeNote.trim().length > VERSION_CHANGE_NOTE_MAX_LENGTH) {
      setNoteError(`Keep the change note to ${VERSION_CHANGE_NOTE_MAX_LENGTH} characters.`);
      return;
    }

    setSubmitting(true);
    try {
      onPublished(await onSubmit(file, changeNote));
    } catch (error) {
      if (isApiError(error, 'UNSUPPORTED_TYPE') || isApiError(error, 'ARTIFACT_TOO_LARGE')) {
        setFileError(error.message);
      } else {
        const issue = isApiError(error) ? error.fieldIssues[0] : undefined;
        if (issue?.path === 'changeNote') setNoteError(issue.message);
        else setFormError(describeError(error));
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form noValidate className="grid gap-4" onSubmit={(event) => void submit(event)}>
      <FormError message={formError} />
      <FileDropZone
        file={file}
        onFileChange={chooseFile}
        maxBytes={config?.maxArtifactBytes}
        error={fileError}
        disabled={submitting}
      />
      <TextAreaField
        label="What changed?"
        hint="Optional"
        rows={3}
        value={changeNote}
        error={noteError}
        disabled={submitting}
        onChange={(event) => {
          setChangeNote(event.target.value);
          setNoteError(undefined);
        }}
      />
      <DialogFooter>
        <DialogClose asChild>
          <Button type="button" variant="outline" disabled={submitting}>
            Cancel
          </Button>
        </DialogClose>
        <Button type="submit" disabled={submitting}>
          {submitting ? 'Uploading…' : 'Upload version'}
        </Button>
      </DialogFooter>
    </form>
  );
}

