import { z } from 'zod';

/** `comment` includes `view`. */
export const SHARE_PERMISSIONS = ['view', 'comment'] as const;
export const sharePermissionSchema = z.enum(SHARE_PERMISSIONS);
export type SharePermission = z.infer<typeof sharePermissionSchema>;

/** `specific_users` arrives with step 14. */
export const SHARE_AUDIENCES = ['anyone_with_link', 'specific_users'] as const;
export type ShareAudience = (typeof SHARE_AUDIENCES)[number];

/** Body of `POST /api/artifacts/:id/shares`. */
export const createShareRequestSchema = z.object({
  audience: z.literal('anyone_with_link'),
  permission: sharePermissionSchema,
  /** When the share stops working; null or absent = never. Must be in the future. */
  expiresAt: z.iso.datetime({ offset: true }).nullable().default(null),
  /** Shares only this version; null or absent = always the latest. */
  versionNo: z.number().int().positive().nullable().default(null),
});

export type CreateShareRequest = z.input<typeof createShareRequestSchema>;
export type CreateShareOptions = z.output<typeof createShareRequestSchema>;

/** A share as the artifact's owner sees it. The link itself is only returned on creation. */
export const shareSchema = z.object({
  id: z.uuid(),
  audience: z.enum(SHARE_AUDIENCES),
  permission: sharePermissionSchema,
  /** The only version it shows; null = always the latest. */
  pinnedVersionNo: z.number().int().positive().nullable(),
  expiresAt: z.iso.datetime().nullable(),
  createdAt: z.iso.datetime(),
