/**
 * SQL condition: the share (aliased `share`) is valid and grants access to the user whose id
 * is `viewer` (a placeholder such as `$1` or `:viewerId`). Valid = not revoked, not expired.
 * Anyone-with-link shares grant access once the user has opened the link.
 *
 * Used both to load grants and to filter lists, so the two always agree.
 */
export function grantingShareSql(share: string, viewer: string): string {
  return `(${share}.revoked_at IS NULL
    AND (${share}.expires_at IS NULL OR ${share}.expires_at > now())
    AND ${share}.audience = 'anyone_with_link'
    AND EXISTS (
      SELECT 1 FROM share_redemptions redemption
      WHERE redemption.share_id = ${share}.id AND redemption.user_id = ${viewer}
    ))`;
}
EOF
cat > access-grants.service.ts <<'EOF'
import { Injectable } from '@nestjs/common';
import type { SharePermission } from '@artifact-hub/shared';
import { DataSource } from 'typeorm';
import type { Actor } from '../auth/auth.types.js';
import type { AccessGrant } from './access.types.js';
import { grantingShareSql } from './granting-shares.js';

interface GrantRow {
  id: string;
  artifact_id: string;
  permission: SharePermission;
  pinned_version_id: string | null;
}

/**
 * Loads the shares that currently grant a user access to artifacts. Read on every request, so
 * revoking or expiring a share takes effect at once.
 */
@Injectable()
export class AccessGrantsService {
  constructor(private readonly dataSource: DataSource) {}

  async forArtifact(actor: Actor, artifactId: string): Promise<AccessGrant[]> {
    return (await this.forArtifacts(actor, [artifactId])).get(artifactId) ?? [];
  }

  /** Grants by artifact id; artifacts without any are missing from the map. */
  async forArtifacts(actor: Actor, artifactIds: string[]): Promise<Map<string, AccessGrant[]>> {
    const grants = new Map<string, AccessGrant[]>();
    if (artifactIds.length === 0) return grants;

    const rows: GrantRow[] = await this.dataSource.query(
      `SELECT share.id, share.artifact_id, share.permission, share.pinned_version_id
       FROM shares share
       WHERE share.artifact_id = ANY($2::uuid[]) AND ${grantingShareSql('share', '$1')}`,
      [actor.userId, artifactIds],
    );
    for (const row of rows) {
      const grant: AccessGrant = {
        shareId: row.id,
        permission: row.permission,
        pinnedVersionId: row.pinned_version_id,
      };
      grants.set(row.artifact_id, [...(grants.get(row.artifact_id) ?? []), grant]);
    }
    return grants;
  }
}
EOF
