cat > sharing.service.ts <<'EOF'
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { type CreateShareOptions, ErrorCode } from '@artifact-hub/shared';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import { IsNull, type Repository } from 'typeorm';
import { z } from 'zod';
import { ArtifactVersion } from '../artifacts/artifact-version.entity.js';
import { ArtifactsService } from '../artifacts/artifacts.service.js';
import type { Actor } from '../auth/auth.types.js';
import { AppError } from '../common/errors/app-error.js';
import {
  generateSecretToken,
  hashSecretToken,
  SECRET_TOKEN_PATTERN,
} from '../common/tokens/secret-tokens.js';
import { InjectEnv } from '../config/config.module.js';
import type { Env } from '../config/config.types.js';
import { ShareRedemption } from './share-redemption.entity.js';
import { Share } from './share.entity.js';
import type { CreatedShare, RedeemDenial, RedeemedShare } from './sharing.types.js';

const idSchema = z.guid();
const SHARE_NOT_FOUND_MESSAGE = 'Share not found.';

/** What the person holding a link is told when it doesn't work. */
const DENIAL_ERRORS: Record<RedeemDenial, AppError> = {
  unknown: new AppError(ErrorCode.NOT_FOUND, "This link doesn't work."),
  artifact_gone: new AppError(ErrorCode.NOT_FOUND, "This link doesn't work."),
  not_for_link: new AppError(ErrorCode.NOT_FOUND, "This link doesn't work."),
  revoked: new AppError(ErrorCode.SHARE_REVOKED, 'This link was turned off by its owner.'),
  expired: new AppError(ErrorCode.SHARE_EXPIRED, 'This link has expired.'),
};

/**
 * Shares of artifacts (plan §1, §4). Only the owner creates, lists and revokes them; any
 * signed-in user may redeem a link. Whether a share grants access is decided per request by
 * `AccessPolicy`, so revoking or expiring one takes effect at once.
 */
@Injectable()
export class SharingService {
  constructor(
    @InjectRepository(Share) private readonly shares: Repository<Share>,
    @InjectRepository(ShareRedemption) private readonly redemptions: Repository<ShareRedemption>,
    @InjectRepository(ArtifactVersion) private readonly versions: Repository<ArtifactVersion>,
    private readonly artifacts: ArtifactsService,
    @InjectEnv() private readonly env: Env,
    @InjectPinoLogger(SharingService.name) private readonly logger: PinoLogger,
  ) {}

  /** Creates an anyone-with-link share and returns its link, which is never shown again. */
  async create(
    actor: Actor,
    artifactId: string,
    options: CreateShareOptions,
  ): Promise<CreatedShare> {
    const { artifact } = await this.artifacts.getForAction(actor, artifactId, 'share');

    const expiresAt = options.expiresAt === null ? null : new Date(options.expiresAt);
    if (expiresAt && expiresAt.getTime() <= Date.now()) {
      throw invalid('expiresAt', 'Choose an expiry date in the future.');
    }
    let pinnedVersion: ArtifactVersion | null = null;
    if (options.versionNo !== null) {
      pinnedVersion = await this.versions.findOneBy({
        artifactId: artifact.id,
        versionNo: options.versionNo,
      });
      if (!pinnedVersion) throw invalid('versionNo', `There is no version ${options.versionNo}.`);
    }

    const token = generateSecretToken();
    const share = await this.shares.save(
      this.shares.create({
        artifactId: artifact.id,
        createdBy: actor.userId,
        tokenHash: hashSecretToken(token),
        permission: options.permission,
        audience: options.audience,
        pinnedVersionId: pinnedVersion?.id ?? null,
        expiresAt,
        revokedAt: null,
      }),
    );
    share.pinnedVersion = pinnedVersion;
    this.logger.info(
      {
        userId: actor.userId,
        artifactId: artifact.id,
        shareId: share.id,
        audience: share.audience,
        permission: share.permission,
        pinnedVersionNo: pinnedVersion?.versionNo ?? null,
        expiresAt,
      },
      'Share created',
    );
    return { share, link: `${this.env.APP_BASE_URL}/s/${token}` };
  }

  /** The artifact's shares that are not revoked (expired ones included), newest first. */
  async list(actor: Actor, artifactId: string): Promise<Share[]> {
    const { artifact } = await this.artifacts.getForAction(actor, artifactId, 'share');
    return this.shares.find({
      where: { artifactId: artifact.id, revokedAt: IsNull() },
      relations: { pinnedVersion: true },
      order: { createdAt: 'DESC', id: 'DESC' },
    });
  }

  /** Turns a share off for everyone at once. Revoking it again does nothing. */
  async revoke(actor: Actor, shareId: string): Promise<void> {
    const share = idSchema.safeParse(shareId).success
      ? await this.shares.findOneBy({ id: shareId })
      : null;
    if (!share) throw new AppError(ErrorCode.NOT_FOUND, SHARE_NOT_FOUND_MESSAGE);
    try {
      await this.artifacts.getForAction(actor, share.artifactId, 'share');
    } catch (error) {
      // Don't reveal shares of artifacts the actor can't see.
      if (error instanceof AppError && error.code === ErrorCode.NOT_FOUND) {
        throw new AppError(ErrorCode.NOT_FOUND, SHARE_NOT_FOUND_MESSAGE);
      }
      throw error;
    }

    const { affected } = await this.shares.update(
      { id: share.id, revokedAt: IsNull() },
      { revokedAt: new Date() },
    );
    if (affected) {
      this.logger.info(
        { userId: actor.userId, artifactId: share.artifactId, shareId: share.id },
        'Share revoked',
      );
    }
  }

  /**
   * Opens a link: records that the actor redeemed it, which grants them access while the share
   * stays valid. The owner opening their own link just gets the artifact.
   */
  async redeem(actor: Actor, token: string): Promise<RedeemedShare> {
    const share = SECRET_TOKEN_PATTERN.test(token)
      ? await this.shares.findOne({
          where: { tokenHash: hashSecretToken(token) },
          relations: { artifact: true },
        })
      : null;

    const isOwner = share?.artifact.ownerId === actor.userId;
    const denial = redeemDenial(share, isOwner);
    if (denial) {
      this.logger.info(
        { userId: actor.userId, shareId: share?.id, artifactId: share?.artifactId, reason: denial },
        'Share redemption denied',
      );
      throw DENIAL_ERRORS[denial];
    }
    // `redeemDenial` returns 'unknown' when there is no share.
    const found = share as Share;

    if (!isOwner) {
      await this.redemptions
        .createQueryBuilder()
        .insert()
        .values({ shareId: found.id, userId: actor.userId })
        .orIgnore()
        .execute();
      this.logger.info(
        { userId: actor.userId, shareId: found.id, artifactId: found.artifactId },
        'Share redeemed',
      );
    }
    return { artifactId: found.artifactId, permission: found.permission };
  }
}

function redeemDenial(share: Share | null, isOwner: boolean): RedeemDenial | null {
  if (!share) return 'unknown';
  const { artifact } = share;
  if (artifact.deletedAt || (artifact.status !== 'published' && !isOwner)) return 'artifact_gone';
  if (share.audience !== 'anyone_with_link') return 'not_for_link';
  if (share.revokedAt) return 'revoked';
  if (share.expiresAt && share.expiresAt.getTime() <= Date.now()) return 'expired';
  return null;
}

function invalid(path: string, message: string): AppError {
  return new AppError(ErrorCode.VALIDATION_FAILED, 'The request is invalid.', [
    { path, message },
  ]);
}
EOF
