import { randomUUID } from 'node:crypto';
import type { NestExpressApplication } from '@nestjs/platform-express';
import {
  apiErrorBodySchema,
  artifactListResponseSchema,
  artifactResponseSchema,
  artifactVersionListResponseSchema,
  type CreateShareRequest,
  createShareResponseSchema,
  ErrorCode,
  redeemShareResponseSchema,
  shareListResponseSchema,
} from '@artifact-hub/shared';
import request, { type Response } from 'supertest';
import { DataSource } from 'typeorm';
import { hashSecretToken } from '../src/common/tokens/secret-tokens.js';
import { createTestApp } from './create-test-app.js';
import { fixtures } from './fixtures/content.js';
import { TEST_ORIGIN } from './test-env.js';
import { type TestUser, testUsers } from './test-users.js';

const LINK: CreateShareRequest = { audience: 'anyone_with_link', permission: 'view' };

function errorOf(res: Response) {
  return apiErrorBodySchema.parse(res.body).error;
}

/** The token at the end of a share link. */
function tokenOf(link: string): string {
  return link.slice(link.lastIndexOf('/') + 1);
}

describe('Sharing (e2e)', () => {
  let app: NestExpressApplication;
  let users: ReturnType<typeof testUsers>;
  let ada: TestUser;
  let bob: TestUser;
  let carol: TestUser;

  beforeAll(async () => {
    app = await createTestApp();
    users = testUsers(app, 'sharing');
    [ada, bob, carol] = await Promise.all([
      users.create('Ada'),
      users.create('Bob'),
      users.create('Carol'),
    ]);
  });

  afterAll(async () => {
    await users.cleanup();
    await app.close();
  });

  const http = () => request(app.getHttpServer());
  const db = () => app.get(DataSource);

  async function publish(user: TestUser, metadata: object = {}): Promise<string> {
    const res = await http()
      .post('/api/artifacts')
      .set('Origin', TEST_ORIGIN)
      .set('Cookie', user.cookie)
      .field('metadata', JSON.stringify({ title: 'Roadmap', ...metadata }))
      .attach('file', fixtures.markdown, 'roadmap.md')
      .expect(201);
    return artifactResponseSchema.parse(res.body).artifact.id;
  }

  async function addVersion(user: TestUser, id: string, file = fixtures.html) {
    await http()
      .post(`/api/artifacts/${id}/versions`)
      .set('Origin', TEST_ORIGIN)
      .set('Cookie', user.cookie)
      .field('metadata', '{}')
      .attach('file', file, 'page.html')
      .expect(201);
  }

  function createShare(user: TestUser, id: string, body: object = LINK) {
    return http()
      .post(`/api/artifacts/${id}/shares`)
      .set('Origin', TEST_ORIGIN)
      .set('Cookie', user.cookie)
      .send(body);
  }

  /** Creates a share as `user` and returns it with its token. */
  async function share(user: TestUser, id: string, body: object = LINK) {
    const res = await createShare(user, id, body).expect(201);
    const created = createShareResponseSchema.parse(res.body);
    return { ...created, token: tokenOf(created.link) };
  }

  function redeem(user: TestUser, token: string) {
    return http().post(`/api/s/${token}`).set('Origin', TEST_ORIGIN).set('Cookie', user.cookie);
  }

  function listShares(user: TestUser, id: string) {
    return http().get(`/api/artifacts/${id}/shares`).set('Cookie', user.cookie);
  }

  function revoke(user: TestUser, shareId: string) {
    return http()
      .delete(`/api/shares/${shareId}`)
      .set('Origin', TEST_ORIGIN)
      .set('Cookie', user.cookie);
  }

  function get(user: TestUser, id: string) {
    return http().get(`/api/artifacts/${id}`).set('Cookie', user.cookie);
  }

  function content(user: TestUser, id: string, versionNo: number) {
    return http().get(`/api/artifacts/${id}/versions/${versionNo}/content`).set('Cookie', user.cookie);
  }

  async function artifactAs(user: TestUser, id: string) {
    return artifactResponseSchema.parse((await get(user, id).expect(200)).body).artifact;
  }

  describe('creating a link', () => {
    it('returns the link once and stores only its hash', async () => {
      const id = await publish(ada);
      const expiresAt = new Date(Date.now() + 7 * 86_400_000).toISOString();
      const res = await createShare(ada, id, { ...LINK, permission: 'comment', expiresAt });
      const { share: created, link } = createShareResponseSchema.parse(res.body);

      expect(res.status).toBe(201);
      expect(link).toMatch(new RegExp(`^${TEST_ORIGIN}/s/[A-Za-z0-9_-]{43}$`));
      expect(created).toMatchObject({
        audience: 'anyone_with_link',
        permission: 'comment',
        pinnedVersionNo: null,
        expiresAt,
      });

      const rows = await db().query('SELECT token_hash FROM shares WHERE id = $1', [created.id]);
      expect(rows).toEqual([{ token_hash: hashSecretToken(tokenOf(link)) }]);
      // The list never includes the link.
      const listed = shareListResponseSchema.parse((await listShares(ada, id).expect(200)).body);
      expect(listed.items).toEqual([created]);
      expect(JSON.stringify(listed)).not.toContain(tokenOf(link));
    });

    it('pins a version', async () => {
      const id = await publish(ada);
      await addVersion(ada, id);
      const { share: created } = await share(ada, id, { ...LINK, versionNo: 1 });
      expect(created.pinnedVersionNo).toBe(1);
    });

    it.each([
      [{ ...LINK, versionNo: 5 }, 'versionNo'],
      [{ ...LINK, expiresAt: new Date(Date.now() - 1000).toISOString() }, 'expiresAt'],
      [{ ...LINK, expiresAt: 'tomorrow' }, 'expiresAt'],
      [{ ...LINK, permission: 'edit' }, 'permission'],
      [{ ...LINK, audience: 'everyone' }, 'audience'],
    ])('rejects %j at %s', async (body, path) => {
      const id = await publish(ada);
      const res = await createShare(ada, id, body).expect(400);
      expect(errorOf(res)).toMatchObject({
        code: ErrorCode.VALIDATION_FAILED,
        details: [expect.objectContaining({ path })],
      });
    });

    it('is only for the owner: 404 without access, 403 with it', async () => {
      const privateId = await publish(ada);
      await createShare(bob, privateId).expect(404);
      await listShares(bob, privateId).expect(404);

      const publicId = await publish(ada, { visibility: 'public' });
      expect(errorOf(await createShare(bob, publicId).expect(403)).code).toBe(
        ErrorCode.FORBIDDEN,
      );
      await listShares(bob, publicId).expect(403);
    });

    it('requires a same-origin request', async () => {
      const id = await publish(ada);
      await createShare(ada, id).set('Origin', 'https://evil.example').expect(403);
    });
  });

  describe('redeeming a link', () => {
    it('gives view access to whoever opens it, from then on', async () => {
      const id = await publish(ada);
      const { token } = await share(ada, id);
      await get(bob, id).expect(404);

      const res = await redeem(bob, token).expect(200);
      expect(redeemShareResponseSchema.parse(res.body)).toEqual({
        artifactId: id,
        permission: 'view',
      });

      expect(await artifactAs(bob, id)).toMatchObject({
        id,
        permissions: { comment: false, edit: false, share: false, delete: false },
      });
      await content(bob, id, 1).expect(200);
      // Opening it again changes nothing.
      await redeem(bob, token).expect(200);
      // Carol never opened it.
      await get(carol, id).expect(404);
    });

    it('lets comment links comment, and still nothing more', async () => {
      const id = await publish(ada);
      const { token } = await share(ada, id, { ...LINK, permission: 'comment' });
      await redeem(bob, token).expect(200);

      expect((await artifactAs(bob, id)).permissions).toEqual({
        comment: true,
        edit: false,
        share: false,
        delete: false,
      });
      await http()
        .patch(`/api/artifacts/${id}`)
        .set('Origin', TEST_ORIGIN)
        .set('Cookie', bob.cookie)
        .send({ title: 'Mine' })
        .expect(403);
      await createShare(bob, id).expect(403);
    });

    it('lets the owner open their own link without recording it', async () => {
      const id = await publish(ada);
      const { token, share: created } = await share(ada, id);
      expect(redeemShareResponseSchema.parse((await redeem(ada, token).expect(200)).body)).toEqual({
        artifactId: id,
        permission: 'view',
      });
      const rows = await db().query('SELECT 1 FROM share_redemptions WHERE share_id = $1', [
        created.id,
      ]);
      expect(rows).toHaveLength(0);
    });

    it.each(['x'.repeat(43), 'not-a-token', randomUUID()])(
      'answers 404 for the unknown token %s',
      async (token) => {
        const res = await redeem(bob, token).expect(404);
        expect(errorOf(res).message).toBe("This link doesn't work.");
      },
    );

    it('answers 404 once the artifact is deleted', async () => {
      const id = await publish(ada);
      const { token } = await share(ada, id);
      await http()
        .delete(`/api/artifacts/${id}`)
        .set('Origin', TEST_ORIGIN)
        .set('Cookie', ada.cookie)
        .expect(204);
      await redeem(bob, token).expect(404);
    });

    it('requires a session and a same-origin request', async () => {
      const id = await publish(ada);
      const { token } = await share(ada, id);
      await http().post(`/api/s/${token}`).set('Origin', TEST_ORIGIN).expect(401);
      await redeem(bob, token).set('Origin', 'https://evil.example').expect(403);
      await get(bob, id).expect(404);
    });
  });

  describe('revoking and expiry', () => {
    it('revoking cuts off everyone who opened the link, at once', async () => {
      const id = await publish(ada);
      const { token, share: created } = await share(ada, id);
      await redeem(bob, token).expect(200);
      await get(bob, id).expect(200);

      await revoke(ada, created.id).expect(204);
      await get(bob, id).expect(404);
      await content(bob, id, 1).expect(404);
      const res = await redeem(carol, token).expect(410);
      expect(errorOf(res)).toMatchObject({
        code: ErrorCode.SHARE_REVOKED,
        message: 'This link was turned off by its owner.',
      });

      const listed = shareListResponseSchema.parse((await listShares(ada, id)).body);
      expect(listed.items).toEqual([]);
      // Revoking again is harmless.
      await revoke(ada, created.id).expect(204);
    });

    it('an expired link stops granting access and says so', async () => {
      const id = await publish(ada);
      const { token, share: created } = await share(ada, id, {
        ...LINK,
        expiresAt: new Date(Date.now() + 60_000).toISOString(),
      });
      await redeem(bob, token).expect(200);
      await get(bob, id).expect(200);

      await db().query("UPDATE shares SET expires_at = now() - interval '1 second' WHERE id = $1", [
        created.id,
      ]);
      await get(bob, id).expect(404);
      const res = await redeem(carol, token).expect(410);
      expect(errorOf(res)).toMatchObject({
        code: ErrorCode.SHARE_EXPIRED,
        message: 'This link has expired.',
      });
      // The owner still sees it, to revoke it.
      const listed = shareListResponseSchema.parse((await listShares(ada, id)).body);
      expect(listed.items.map((item) => item.id)).toEqual([created.id]);
    });

    it("can't be done by anyone but the owner, nor reveal other users' shares", async () => {
      const id = await publish(ada);
      const { token, share: created } = await share(ada, id);
      const unknown = await revoke(bob, randomUUID()).expect(404);
      const hidden = await revoke(bob, created.id).expect(404);
      expect(errorOf(hidden).message).toBe(errorOf(unknown).message);

      await redeem(bob, token).expect(200);
      await revoke(bob, created.id).expect(403);
      await get(bob, id).expect(200);
    });
  });

  describe('pinned versions', () => {
    it('shows recipients only the pinned version, even after new ones', async () => {
      const id = await publish(ada);
      await addVersion(ada, id);
      const { token } = await share(ada, id, { ...LINK, versionNo: 1 });
      await redeem(bob, token).expect(200);

      const seen = await artifactAs(bob, id);
      expect(seen).toMatchObject({ latestVersionNo: 1, currentVersion: { versionNo: 1 } });
      const versions = await http()
        .get(`/api/artifacts/${id}/versions`)
        .set('Cookie', bob.cookie)
        .expect(200);
      expect(
        artifactVersionListResponseSchema.parse(versions.body).items.map((v) => v.versionNo),
      ).toEqual([1]);
      await content(bob, id, 1).expect(200);
      await content(bob, id, 2).expect(404);

      await addVersion(ada, id, fixtures.svg);
      expect((await artifactAs(bob, id)).currentVersion?.versionNo).toBe(1);
      expect((await artifactAs(ada, id)).currentVersion?.versionNo).toBe(3);
    });

    it('an unpinned link next to a pinned one shows every version', async () => {
      const id = await publish(ada);
      await addVersion(ada, id);
      await redeem(bob, (await share(ada, id, { ...LINK, versionNo: 1 })).token).expect(200);
      await redeem(bob, (await share(ada, id)).token).expect(200);

      expect(await artifactAs(bob, id)).toMatchObject({
        latestVersionNo: 2,
        currentVersion: { versionNo: 2 },
      });
      await content(bob, id, 1).expect(200);
    });
  });

  it('keeps shared artifacts out of the Mine and All public lists', async () => {
    const id = await publish(ada);
    await redeem(bob, (await share(ada, id)).token).expect(200);
    for (const scope of ['mine', 'public']) {
      const res = await http()
        .get('/api/artifacts')
        .query({ scope, pageSize: 50 })
        .set('Cookie', bob.cookie)
        .expect(200);
      const ids = artifactListResponseSchema.parse(res.body).items.map((item) => item.id);
      expect(ids).not.toContain(id);
    }
  });
});

