import {
  type CreateShareRequest,
  type CreateShareResponse,
  createShareResponseSchema,
  type RedeemShareResponse,
  redeemShareResponseSchema,
  type Share,
  shareListResponseSchema,
} from '@artifact-hub/shared';
import { artifactQueryKey } from '@/features/artifacts/artifacts-api.ts';
import { apiRequest } from '@/lib/api/client.ts';

/** Under the artifact's key, so it goes with the artifact's other queries. */
export const sharesQueryKey = (artifactId: string) =>
  [...artifactQueryKey(artifactId), 'shares'] as const;

const sharesPath = (artifactId: string) => `/artifacts/${encodeURIComponent(artifactId)}/shares`;

/** Shares not revoked (expired ones included), newest first. Owner only. */
export async function fetchShares(artifactId: string, signal?: AbortSignal): Promise<Share[]> {
  return (await apiRequest(sharesPath(artifactId), { schema: shareListResponseSchema, signal }))
    .items;
}

/** The response has the link; it is never shown again. */
export async function createShare(
  artifactId: string,
  body: CreateShareRequest,
): Promise<CreateShareResponse> {
  return apiRequest(sharesPath(artifactId), {
    method: 'POST',
    body,
    schema: createShareResponseSchema,
  });
}

export async function revokeShare(shareId: string): Promise<void> {
  await apiRequest(`/shares/${encodeURIComponent(shareId)}`, { method: 'DELETE' });
}

export async function redeemShare(token: string): Promise<RedeemShareResponse> {
  return apiRequest(`/s/${encodeURIComponent(token)}`, {
    method: 'POST',
    schema: redeemShareResponseSchema,
  });
}
