import type { CreateShareRequest } from '@artifact-hub/shared';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { artifactListsQueryKey, artifactQueryKey } from '@/features/artifacts/artifacts-api.ts';
import { createShare, fetchShares, redeemShare, revokeShare, sharesQueryKey } from './sharing-api.ts';

export function useShares(artifactId: string) {
  return useQuery({
    queryKey: sharesQueryKey(artifactId),
    queryFn: ({ signal }) => fetchShares(artifactId, signal),
  });
}

export function useCreateShare(artifactId: string) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateShareRequest) => createShare(artifactId, body),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: sharesQueryKey(artifactId) }),
  });
}

export function useRevokeShare(artifactId: string) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: revokeShare,
    onSuccess: () => queryClient.invalidateQueries({ queryKey: sharesQueryKey(artifactId) }),
  });
}

/**
 * Redeeming grants access: drop anything cached about the artifact (a remembered 404, say) and
 * refresh the lists it may now appear in.
 */
export function useRedeemShare() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: redeemShare,
    onSuccess: ({ artifactId }) => {
      queryClient.removeQueries({ queryKey: artifactQueryKey(artifactId) });
      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
    },
  });
}
EOF
