import { type Artifact, SHARE_PERMISSIONS, sharePermissionSchema } from '@artifact-hub/shared';
import { zodResolver } from '@hookform/resolvers/zod';
import { LinkIcon } from 'lucide-react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { FormError, SelectField } from '@/components/form-fields.tsx';
import { Button } from '@/components/ui/button.tsx';
import { useArtifactVersions } from '@/features/artifacts/use-artifacts.ts';
import { describeError, isApiError } from '@/lib/api/api-error.ts';
import { EXPIRY_PRESETS, expiresAtFor, PERMISSION_LABELS } from './share-labels.ts';
import { useCreateShare } from './use-sharing.ts';

const LATEST = 'latest';

const createLinkFormSchema = z.object({
  permission: sharePermissionSchema,
  expiry: z.enum(EXPIRY_PRESETS.map((preset) => preset.value)),
  /** `latest`, or the number of the only version to share. */
  version: z.string(),
});

type CreateLinkFormValues = z.infer<typeof createLinkFormSchema>;

/** Creates an anyone-with-link share; `onCreated` gets its link, which is shown only once. */
export function CreateLinkForm({
  artifact,
  onCreated,
}: {
  artifact: Artifact;
  onCreated: (link: string) => void;
}) {
  const create = useCreateShare(artifact.id);
  const { data: versions } = useArtifactVersions(artifact.id);
  const {
    register,
    handleSubmit,
    setError,
    formState: { errors, isSubmitting },
  } = useForm<CreateLinkFormValues>({
    resolver: zodResolver(createLinkFormSchema),
    defaultValues: { permission: 'view', expiry: '7', version: LATEST },
  });

  const submit = handleSubmit(async ({ permission, expiry, version }) => {
    try {
      const { link } = await create.mutateAsync({
        audience: 'anyone_with_link',
        permission,
        expiresAt: expiresAtFor(expiry),
        versionNo: version === LATEST ? null : Number(version),
      });
      onCreated(link);
    } catch (error) {
      const issue = isApiError(error) ? error.fieldIssues[0] : undefined;
      setError('root.server', { message: issue?.message ?? describeError(error) });
    }
  });

  return (
    <form noValidate className="grid gap-4" onSubmit={(event) => void submit(event)}>
      <FormError message={errors.root?.server?.message} />
      <div className="grid gap-4 sm:grid-cols-3">
        <SelectField label="Access" disabled={isSubmitting} {...register('permission')}>
          {SHARE_PERMISSIONS.map((permission) => (
            <option key={permission} value={permission}>
              {PERMISSION_LABELS[permission]}
            </option>
          ))}
        </SelectField>
        <SelectField label="Expires after" disabled={isSubmitting} {...register('expiry')}>
          {EXPIRY_PRESETS.map((preset) => (
            <option key={preset.value} value={preset.value}>
              {preset.label}
            </option>
          ))}
        </SelectField>
        <SelectField label="Version" disabled={isSubmitting} {...register('version')}>
          <option value={LATEST}>Always the latest</option>
          {versions?.map((version) => (
            <option key={version.id} value={String(version.versionNo)}>
              Only v{version.versionNo}
            </option>
          ))}
        </SelectField>
      </div>
      <div>
        <Button type="submit" disabled={isSubmitting}>
          <LinkIcon aria-hidden="true" />
          {isSubmitting ? 'Creating…' : 'Create link'}
        </Button>
      </div>
    </form>
  );
}
