// @vitest-environment jsdom
import type { Artifact, ArtifactVersion, User } from '@artifact-hub/shared';
import { cleanup, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { installFakeApi } from '@/test/fake-api.ts';
import { renderApp } from '@/test/render-app.tsx';

const DAY = 24 * 60 * 60_000;

function version(versionNo: number): ArtifactVersion {
  return {
    id: crypto.randomUUID(),
    versionNo,
    mimeType: 'text/html',
    sizeBytes: 100,
    sha256: String(versionNo).repeat(64),
    originalFilename: 'page.html',
    changeNote: null,
    createdAt: new Date().toISOString(),
  };
}

describe('share dialog', () => {
  let api: ReturnType<typeof installFakeApi>;
  let me: User;

  beforeEach(() => {
    api = installFakeApi();
    me = api.addAccount('ada@example.com', 'correct horse', 'Ada Lovelace');
    api.signIn(me);
  });

  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
  });

  /** An artifact with two versions, mine unless `owner` says otherwise. */
  function artifact(owner: Artifact['owner'] = { id: me.id, displayName: me.displayName }) {
    const versions = [version(1), version(2)];
    const now = new Date().toISOString();
    const item: Artifact = {
      id: crypto.randomUUID(),
      title: 'Roadmap',
      description: '',
      tags: [],
      visibility: 'private',
      status: 'published',
      metadataSource: 'user',
      owner,
      currentVersion: versions[1]!,
      latestVersionNo: 2,
      permissions: { comment: true, edit: true, share: true, delete: true },
      createdAt: now,
      updatedAt: now,
    };
    api.addArtifact(item, '<p>hi</p>', versions);
    return item;
  }

  async function openDialog(item: Artifact) {
    const user = userEvent.setup();
    renderApp(`/artifacts/${item.id}`);
    await user.click(await screen.findByRole('button', { name: 'Share' }));
    const dialog = await screen.findByRole('dialog', { name: 'Share “Roadmap”' });
    return { user, dialog };
  }

  it('creates a link with the chosen access, expiry and version, and shows it once', async () => {
    const item = artifact();
    const { user, dialog } = await openDialog(item);
    expect(await within(dialog).findByText('No links yet.')).toBeTruthy();

    await user.selectOptions(within(dialog).getByLabelText('Access'), 'Can comment');
    await user.selectOptions(within(dialog).getByLabelText('Expires after'), '30 days');
    await within(dialog).findByRole('option', { name: 'Only v1' });
    await user.selectOptions(within(dialog).getByLabelText('Version'), 'Only v1');
    await user.click(within(dialog).getByRole('button', { name: 'Create link' }));

    const link = (await within(dialog).findByLabelText('New link')) as HTMLInputElement;
    expect(link.value).toBe('http://localhost:5173/s/token-1');
    const [created] = api.shares(item.id);
    expect(created).toMatchObject({ permission: 'comment', pinnedVersionNo: 1 });
    const expiresIn = new Date(created!.expiresAt!).getTime() - Date.now();
    expect(Math.abs(expiresIn - 30 * DAY)).toBeLessThan(60_000);

    const row = within(await within(dialog).findByRole('list', { name: 'Links' })).getByRole(
      'listitem',
    );
    expect(row.textContent).toContain('Can comment');
    expect(row.textContent).toContain('Only v1');
    expect(row.textContent).toContain('Expires in 30 days');
  });

  it('defaults to a view link for the latest version that expires in 7 days', async () => {
    const item = artifact();
    const { user, dialog } = await openDialog(item);
    await user.click(within(dialog).getByRole('button', { name: 'Create link' }));
    await within(dialog).findByLabelText('New link');

    const [created] = api.shares(item.id);
    expect(created).toMatchObject({ permission: 'view', pinnedVersionNo: null });
    const expiresIn = new Date(created!.expiresAt!).getTime() - Date.now();
    expect(Math.abs(expiresIn - 7 * DAY)).toBeLessThan(60_000);
  });

  it('copies the new link, and forgets it when the dialog closes', async () => {
    const item = artifact();
    const { user, dialog } = await openDialog(item);
    await user.click(within(dialog).getByRole('button', { name: 'Create link' }));
    await within(dialog).findByLabelText('New link');

    const writeText = vi.spyOn(navigator.clipboard, 'writeText');
    await user.click(within(dialog).getByRole('button', { name: 'Copy' }));
    expect(writeText).toHaveBeenCalledWith('http://localhost:5173/s/token-1');

    await user.keyboard('{Escape}');
    await user.click(screen.getByRole('button', { name: 'Share' }));
    const reopened = await screen.findByRole('dialog');
    await within(reopened).findByRole('list', { name: 'Links' });
    expect(within(reopened).queryByLabelText('New link')).toBeNull();
  });

  it('revokes a link and marks expired ones', async () => {
    const item = artifact();
    api.addShareLink(item.id, 'old', { expiresAt: new Date(Date.now() - DAY).toISOString() });
    api.addShareLink(item.id, 'current');
    const { user, dialog } = await openDialog(item);

    const list = await within(dialog).findByRole('list', { name: 'Links' });
    const rows = within(list).getAllByRole('listitem');
    expect(rows.map((row) => row.textContent?.includes('Expired'))).toEqual([true, false]);

    await user.click(within(rows[1]!).getByRole('button', { name: 'Revoke' }));
    await waitFor(() => expect(within(list).getAllByRole('listitem')).toHaveLength(1));
    expect(api.shares(item.id)).toHaveLength(1);
  });

  it('is only offered to the owner', async () => {
    const item = artifact({ id: crypto.randomUUID(), displayName: 'Grace Hopper' });
    renderApp(`/artifacts/${item.id}`);
    expect(await screen.findByRole('heading', { name: 'Roadmap' })).toBeTruthy();
    expect(screen.queryByRole('button', { name: 'Share' })).toBeNull();
  });
});
EOF
