import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { installFakeApi } from '@/test/fake-api.ts';
import { renderApp } from '@/test/render-app.tsx';

describe('share link page', () => {
  let api: ReturnType<typeof installFakeApi>;
  let item: Artifact;

  beforeEach(() => {
    api = installFakeApi();
    api.addAccount('ada@example.com', 'correct horse');
    const now = new Date().toISOString();
    item = {
      id: crypto.randomUUID(),
      title: 'Roadmap',
      description: '',
      tags: [],
      visibility: 'private',
      status: 'published',
      metadataSource: 'user',
      owner: { id: crypto.randomUUID(), displayName: 'Grace Hopper' },
      currentVersion: null,
      latestVersionNo: 0,
      permissions: { comment: false, edit: false, share: false, delete: false },
      createdAt: now,
      updatedAt: now,
    };
    api.addArtifact(item);
  });

  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
  });

  const signIn = () => api.signIn(api.addAccount('bob@example.com', 'pw', 'Bob'));

  it('opens the link once and goes on to the artifact', async () => {
    signIn();
    api.addShareLink(item.id, 'abc');
    const app = renderApp('/s/abc');

    expect(await screen.findByRole('heading', { name: 'Roadmap' })).toBeTruthy();
    expect(app.location()).toBe(`/artifacts/${item.id}`);
    expect(api.calls('POST /api/s/abc')).toBe(1);
  });

  it('asks to log in first, and comes back to the link', async () => {
    api.addShareLink(item.id, 'abc');
    const app = renderApp('/s/abc');
    await waitFor(() => expect(app.location()).toBe('/login?next=%2Fs%2Fabc'));
    expect(api.calls('POST /api/s/abc')).toBe(0);
  });

  it.each([
    ['expired', { expiresAt: new Date(Date.now() - 1000).toISOString() }, 'This link has expired'],
    ['revoked', { revoked: true }, 'This link was turned off'],
  ])('explains a %s link', async (_, state, heading) => {
    signIn();
    api.addShareLink(item.id, 'abc', state);
    renderApp('/s/abc');
    expect(await screen.findByRole('heading', { name: heading })).toBeTruthy();
    expect(screen.getByText('Ask the person who shared it with you for a new link.')).toBeTruthy();
  });

  it('explains a link that does not exist', async () => {
    signIn();
    renderApp('/s/nope');
    expect(await screen.findByRole('heading', { name: "This link doesn't work" })).toBeTruthy();
  });
});
