    expect(row.textContent).toContain('Only v1');
    expect(row.textContent).toContain('Expires in 30 days');
  });

  it('defaults to a view link for the latest version that expires in 7 days', async () => {
    const item = artifact();
    const { user, dialog } = await openDialog(item);
