import type { Artifact } from '@artifact-hub/shared';
import { CopyIcon } from 'lucide-react';
import { type ReactNode, useState } from 'react';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button.tsx';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog.tsx';
import { Input } from '@/components/ui/input.tsx';
import { CreateLinkForm } from './create-link-form.tsx';
import { ShareList } from './share-list.tsx';

/** Shares `artifact` through links; opened from `children` (the trigger). Owner only. */
export function ShareDialog({ artifact, children }: { artifact: Artifact; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const [createdLink, setCreatedLink] = useState<string | null>(null);

  const onOpenChange = (next: boolean) => {
    // A link is shown once: closing the dialog forgets it.
    if (!next) setCreatedLink(null);
    setOpen(next);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      {/* The header stays put; the rest scrolls. */}
      <DialogContent className="flex flex-col overflow-hidden sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>Share “{artifact.title}”</DialogTitle>
          <DialogDescription>
            Anyone signed in who opens a link can see the artifact, until the link expires or you
            revoke it.
          </DialogDescription>
        </DialogHeader>
        <div className="-m-1 grid min-h-0 gap-6 overflow-y-auto p-1">
          <section className="grid gap-3" aria-labelledby="share-new-link">
            <h3 id="share-new-link" className="text-sm font-semibold">
              Create a link
            </h3>
            <CreateLinkForm artifact={artifact} onCreated={setCreatedLink} />
            {createdLink ? <CreatedLink link={createdLink} /> : null}
          </section>
          <section className="grid gap-3" aria-labelledby="share-links">
            <h3 id="share-links" className="text-sm font-semibold">
              Links
            </h3>
            <ShareList artifactId={artifact.id} />
          </section>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/** The link just created, the only time it can be copied. */
function CreatedLink({ link }: { link: string }) {
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(link);
      toast.success('Link copied');
    } catch {
      toast.error("Couldn't copy the link. Select it and copy it yourself.");
    }
  };

  return (
    <div role="status" className="grid gap-2 rounded-lg border bg-muted p-3">
      <p className="text-sm">Copy the link now. For security, it won't be shown again.</p>
      <div className="flex gap-2">
        <Input
          readOnly
          value={link}
          aria-label="New link"
          onFocus={(event) => event.target.select()}
          className="bg-background font-mono text-xs"
        />
        <Button type="button" variant="outline" onClick={() => void copy()}>
          <CopyIcon aria-hidden="true" />
          Copy
        </Button>
      </div>
    </div>
  );
}

