export function ShareDialog({ artifact, children }: { artifact: Artifact; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const [createdLink, setCreatedLink] = useState<string | null>(null);
  const isPublic = artifact.visibility === 'public';

  const onOpenChange = (next: boolean) => {
    // A link is shown once: closing the dialog forgets it.
    if (!next) setCreatedLink(null);
    setOpen(next);
  };

  return (
