              : 'Anyone signed in who opens a link can see the artifact, until the link expires or you revoke it.'}
          </DialogDescription>
        </DialogHeader>
        <div className="-m-1 grid min-h-0 gap-6 overflow-y-auto p-1">
          {isPublic ? (
