                  className="flex items-center gap-2 text-sm font-semibold"
                >
                  <GlobeIcon className="size-4 text-muted-foreground" aria-hidden="true" />
                  Link to this artifact
                </h3>
                <CopyableLink
                  link={`${window.location.origin}/artifacts/${artifact.id}`}
                  label="Artifact link"
                />
              </section>
              <EarlierLinks artifactId={artifact.id} />
            </>
          ) : (
            <>
              <section className="grid gap-3" aria-labelledby="share-new-link">
                <h3 id="share-new-link" className="text-sm font-semibold">
                  Create a link
                </h3>
                <CreateLinkForm artifact={artifact} onCreated={setCreatedLink} />
                {createdLink ? (
                  <div role="status" className="grid gap-2 rounded-lg border bg-muted p-3">
                    <p className="text-sm">
                      Copy the link now. For security, it won't be shown again.
                    </p>
                    <CopyableLink link={createdLink} label="New link" />
                  </div>
                ) : null}
              </section>
              <section className="grid gap-3" aria-labelledby="share-links">
                <h3 id="share-links" className="text-sm font-semibold">
                  Links
                </h3>
                <ShareList artifactId={artifact.id} />
              </section>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Links created while the artifact was private, if any: they keep granting access if it goes
 * private again, so they stay listed for revoking.
 */
function EarlierLinks({ artifactId }: { artifactId: string }) {
  const { data: shares } = useShares(artifactId);
  if (!shares?.length) return null;
  return (
    <section className="grid gap-3" aria-labelledby="share-links">
      <h3 id="share-links" className="text-sm font-semibold">
        Links
      </h3>
      <p className="text-sm text-muted-foreground">
        People who opened these keep access if you make the artifact private again.
      </p>
      <ShareList artifactId={artifactId} />
    </section>
  );
}

