import { Body, Controller, Delete, Get, HttpCode, HttpStatus, Param, Post } from '@nestjs/common';
import {
  type CreateShareOptions,
  type CreateShareResponse,
  type RedeemShareResponse,
  type ShareListResponse,
  createShareRequestSchema,
} from '@artifact-hub/shared';
import { CurrentActor } from '../auth/auth.decorators.js';
import type { Actor } from '../auth/auth.types.js';
import { ZodValidationPipe } from '../common/validation/zod-validation.pipe.js';
import { toShareDto } from './share.entity.js';
import { SharingService } from './sharing.service.js';

@Controller()
export class SharingController {
  constructor(private readonly sharing: SharingService) {}

  /** The response carries the link; it can't be retrieved again. */
  @Post('artifacts/:id/shares')
  async create(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Body(new ZodValidationPipe(createShareRequestSchema)) options: CreateShareOptions,
  ): Promise<CreateShareResponse> {
    const { share, link } = await this.sharing.create(actor, artifactId, options);
    return { share: toShareDto(share), link };
  }

  @Get('artifacts/:id/shares')
  async list(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
  ): Promise<ShareListResponse> {
    const shares = await this.sharing.list(actor, artifactId);
    return { items: shares.map(toShareDto) };
  }

  @Delete('shares/:id')
  @HttpCode(HttpStatus.NO_CONTENT)
  async revoke(@CurrentActor() actor: Actor, @Param('id') shareId: string): Promise<void> {
    await this.sharing.revoke(actor, shareId);
  }

  /**
   * Redeems a link. A POST, not a GET: it grants access, so it goes through the CSRF check and
   * a third-party page can't make a signed-in user redeem a link.
   */
  @Post('s/:token')
  @HttpCode(HttpStatus.OK)
  async redeem(
    @CurrentActor() actor: Actor,
    @Param('token') token: string,
  ): Promise<RedeemShareResponse> {
    return this.sharing.redeem(actor, token);
  }
}

