import { describeError } from '@/lib/api/api-error.ts';
import { PermissionSelect, VersionSelect } from './access-selects.tsx';
import { useRemovePerson, useUpdatePerson } from './use-sharing.ts';

/** The owner, then everyone the artifact is shared with; changes are saved as they are made. */
export function PeopleList({ artifact, people }: { artifact: Artifact; people: SharedPerson[] }) {
  const update = useUpdatePerson(artifact.id);
  const remove = useRemovePerson(artifact.id);
  const onError = (error: unknown) => toast.error(describeError(error));

  return (
    <ul className="grid gap-1" aria-label="People with access">
      <li className="flex items-center gap-3 py-1.5 text-sm">
        <span className="min-w-0 flex-1 truncate font-medium">
          {artifact.owner.displayName} (you)
        </span>
        <span className="text-muted-foreground">Owner</span>
      </li>
      {people.map((person) => {
        const { user } = person;
        const busy =
          (update.isPending && update.variables.userId === user.id) ||
          (remove.isPending && remove.variables === user.id);
        return (
          <li key={user.id} className="flex flex-wrap items-center gap-2 py-1.5 text-sm">
            <span className="grid min-w-0 flex-1 basis-40">
              <span className="truncate font-medium">{user.displayName}</span>
              <span className="truncate text-xs text-muted-foreground">{user.email}</span>
            </span>
            <PermissionSelect
              aria-label={`Permission for ${user.displayName}`}
              value={person.permission}
              disabled={busy}
              onChange={(permission) =>
                update.mutate({ userId: user.id, permission }, { onError })
              }
            />
            <VersionSelect
              aria-label={`Version for ${user.displayName}`}
              artifactId={artifact.id}
              value={person.pinnedVersionNo}
              disabled={busy}
              onChange={(versionNo) => update.mutate({ userId: user.id, versionNo }, { onError })}
            />
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={`Remove ${user.displayName}`}
              disabled={busy}
              onClick={() => remove.mutate(user.id, { onError })}
            >
              <XIcon aria-hidden="true" />
            </Button>
          </li>
        );
      })}
    </ul>
  );
}
