      {SHARE_PERMISSIONS.map((permission) => (
        <option key={permission} value={permission}>
          {PERMISSION_LABELS[permission]}
        </option>
      ))}
    </NativeSelect>
  );
}

const LATEST = 'latest';

/** "Latest version" or "Only vN": `null` stands for the latest. */
export function VersionSelect({
  artifactId,
  value,
  onChange,
  ...props
}: SelectProps & {
  artifactId: string;
  value: number | null;
  onChange: (versionNo: number | null) => void;
}) {
  const { data: versions } = useArtifactVersions(artifactId);
  return (
    <NativeSelect
      value={value === null ? LATEST : String(value)}
      onChange={(event) =>
        onChange(event.target.value === LATEST ? null : Number(event.target.value))
      }
      {...props}
    >
      <option value={LATEST}>Latest version</option>
      {versions?.map((version) => (
        <option key={version.id} value={String(version.versionNo)}>
          Only v{version.versionNo}
        </option>
      ))}
      {/* A pinned version shows even before the list has loaded. */}
      {value !== null && !versions ? <option value={String(value)}>Only v{value}</option> : null}
    </NativeSelect>
  );
}
