import type { Artifact } from '@artifact-hub/shared';
import { LinkIcon } from 'lucide-react';
import { type ReactNode, useState } from 'react';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';
import { Button } from '@/components/ui/button.tsx';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog.tsx';
import { copyWithToast } from '@/lib/clipboard.ts';
import { AddPeopleForm } from './add-people-form.tsx';
import { CompanyAccess } from './company-access.tsx';
import { PeopleList } from './people-list.tsx';
import { useAccess } from './use-sharing.ts';

/** Who can see `artifact`, like Google Docs' share dialog. Owner only; opened from `children`. */
export function ShareDialog({ artifact, children }: { artifact: Artifact; children: ReactNode }) {
  const [open, setOpen] = useState(false);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      {/* Header and footer stay put; the rest scrolls. */}
      <DialogContent className="flex flex-col overflow-hidden sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>Share “{artifact.title}”</DialogTitle>
          <DialogDescription>Changes are saved as you make them.</DialogDescription>
        </DialogHeader>
        {open ? <ShareDialogBody artifact={artifact} /> : null}
        <DialogFooter className="sm:justify-between">
          <Button
            variant="outline"
            onClick={() =>
              void copyWithToast(`${window.location.origin}/artifacts/${artifact.id}`)
            }
          >
            <LinkIcon aria-hidden="true" />
            Copy link
          </Button>
          <DialogClose asChild>
            <Button>Done</Button>
          </DialogClose>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function ShareDialogBody({ artifact }: { artifact: Artifact }) {
  const { data: access, error, refetch } = useAccess(artifact.id);

  if (error) return <InlineError error={error} onRetry={() => void refetch()} />;
  if (!access) {
    return (
      <div className="h-40">
        <InlineLoading />
      </div>
    );
  }
  return (
    <div className="-m-1 grid min-h-0 gap-6 overflow-y-auto p-1">
      <section className="grid gap-3" aria-labelledby="share-people">
        <h3 id="share-people" className="text-sm font-semibold">
          People
        </h3>
        <AddPeopleForm artifactId={artifact.id} />
        <PeopleList artifact={artifact} people={access.people} />
      </section>
      <section className="grid gap-3" aria-labelledby="share-general">
        <h3 id="share-general" className="text-sm font-semibold">
          General access
        </h3>
        <CompanyAccess artifactId={artifact.id} company={access.company} />
      </section>
    </div>
  );
}
