import { useQuery } from '@tanstack/react-query';
import Markdown, { type Components } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { artifactQueryKey, fetchArtifactText } from '../artifacts-api.ts';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';

/** Links leave the app in a new tab, without telling the target where they came from. */
const components: Components = {
  a: ({ node: _node, ...props }) => <a {...props} target="_blank" rel="noopener noreferrer" />,
};

/**
 * Renders Markdown as React elements. Raw HTML in the source is shown as text, never parsed
 * (no `rehype-raw`), and react-markdown's default URL filter drops `javascript:` and similar
 * links, so the content can't inject markup or scripts into the app. Loaded lazily (default
 * export for `React.lazy`), like the PDF viewer.
 */
export default function MarkdownViewer({
  artifactId,
  versionNo,
}: {
  artifactId: string;
  versionNo: number;
}) {
  const { data, error, refetch } = useQuery({
    queryKey: [...artifactQueryKey(artifactId), 'versions', versionNo, 'text'],
    queryFn: ({ signal }) => fetchArtifactText(artifactId, versionNo, signal),
    // A version's content never changes.
    staleTime: Infinity,
  });

  if (error) return <InlineError error={error} onRetry={() => void refetch()} />;
  if (data === undefined) return <InlineLoading />;
  return (
    <div className="size-full overflow-auto bg-background">
      <article className="prose prose-neutral mx-auto max-w-3xl px-6 py-8 dark:prose-invert">
        <Markdown remarkPlugins={[remarkGfm]} components={components}>
          {data}
        </Markdown>
      </article>
    </div>
  );
}
import { getDocument, GlobalWorkerOptions, type PDFDocumentLoadingTask } from 'pdfjs-dist';
// Vite's `?url` import (the worker's URL); oxlint can't resolve it.
// oxlint-disable-next-line import/default
import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
import { useEffect, useRef, useState } from 'react';
import { isApiError } from '@/lib/api/api-error.ts';
import { fetchArtifactBytes } from '../artifacts-api.ts';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';

GlobalWorkerOptions.workerSrc = workerUrl;

/** Rendering every page of a huge PDF up front would stall the tab. */
const MAX_PAGES = 100;

type PdfState =
  | { status: 'loading' }
  | { status: 'ready'; pageCount: number }
  | { status: 'error'; error: unknown };

/**
 * Renders a PDF to canvases with pdf.js. Browsers refuse to show PDFs in their built-in viewer
 * under a CSP sandbox, so we fetch the bytes and draw the pages ourselves. pdf.js never runs
 * the document's own JavaScript (and since v6 doesn't use `eval` either). Loaded lazily
 * (default export for `React.lazy`), so pdf.js is only downloaded for PDFs.
 */
export default function PdfViewer(props: { artifactId: string; versionNo: number }) {
  // "Try again" remounts the document with a fresh state.
  const [attempt, setAttempt] = useState(0);
  return <PdfDocument key={attempt} {...props} onRetry={() => setAttempt((n) => n + 1)} />;
}

function PdfDocument({
  artifactId,
  versionNo,
  onRetry,
}: {
  artifactId: string;
import type { ArtifactMimeType } from '@artifact-hub/shared';

/**
 * CSP for every content response (plan §7, S1). `sandbox` without `allow-same-origin` gives the
 * document an opaque origin, so its scripts can't read app cookies or call the API, even when
 * the content URL is opened directly. External https resources (CDN scripts, styles, fonts,
 * images) may load so AI-generated HTML renders as intended; network APIs (fetch, XHR,
 * WebSocket), form submission, nested frames and `<base>` stay blocked, and only the app
 * itself may frame the content.
 */
export const CONTENT_SECURITY_POLICY = [
  'sandbox allow-scripts allow-popups',
  "default-src 'none'",
  "script-src 'unsafe-inline' 'unsafe-eval' https: data: blob:",
  "style-src 'unsafe-inline' https: data:",
  'img-src https: data: blob:',
  'font-src https: data:',
  'media-src https: data: blob:',
  "connect-src 'none'",
  "frame-src 'none'",
  "form-action 'none'",
  "base-uri 'none'",
  "frame-ancestors 'self'",
].join('; ');

const TEXT_MIME_TYPES = new Set<ArtifactMimeType>(['text/html', 'text/markdown', 'image/svg+xml']);

/** `Content-Type` as served: text formats are always UTF-8 (enforced at upload). */
export function servedContentType(mimeType: ArtifactMimeType): string {
  return TEXT_MIME_TYPES.has(mimeType) ? `${mimeType}; charset=utf-8` : mimeType;
}

/** True if an `If-None-Match` header lists `etag` (or `*`); weak validators count as equal. */
export function etagMatches(ifNoneMatch: string | undefined, etag: string): boolean {
  if (!ifNoneMatch) return false;
  return ifNoneMatch
    .split(',')
    .map((tag) => tag.trim().replace(/^W\//, ''))
    .some((tag) => tag === '*' || tag === etag);
}

/** Headers sent with every content response, whatever the type. */
export const CONTENT_SECURITY_HEADERS: Readonly<Record<string, string>> = {
  'Content-Security-Policy': CONTENT_SECURITY_POLICY,
  'X-Content-Type-Options': 'nosniff',
  'Cross-Origin-Resource-Policy': 'same-origin',
  'Referrer-Policy': 'no-referrer',
  // Versions never change, but access can be revoked: the browser may keep a copy, and must
  // revalidate it (a cheap 304 through the access check) before every use.
  'Cache-Control': 'private, no-cache',
};
