  it('refuses altered tokens and other keys', () => {
    const sealed = cipher.seal('a-token');
    const [version, iv, tag, ciphertext] = sealed.split('.');
    const flipped = Buffer.from(ciphertext!, 'base64url');
    flipped[0]! ^= 1;
