      const res = await http()
        .get('/api/artifacts')
        .query({ q: 'x'.repeat(201) })
        .set('Cookie', ada.cookie)
        .expect(400);
      expect(apiErrorBodySchema.parse(res.body).error.code).toBe(ErrorCode.VALIDATION_FAILED);
    });
  });

  describe('filters', () => {
