      expect((await titles(ada, { q: word, tag: 'Q3' })).toSorted()).toEqual(
        [`Deck ${word}`, `Mockup ${word}`].toSorted(),
      );
      expect(await titles(ada, { q: word, tag: 'q3', type: 'html' })).toEqual([`Mockup ${word}`]);
    });

    it('rejects unknown types', async () => {
