        .expect(200);
      expect(artifactTagListResponseSchema.parse(res.body).items).toEqual([
        { tag: 'beta', count: 2 },
        { tag: 'alpha', count: 1 },
      ]);
    });

    it('never includes tags of artifacts the user may not see', async () => {
      const dave = await users.create('Dave');
